#define STAN_MAJOR 2
#define STAN_MINOR 40
#define STAN_PATCH 0

namespace stan {

/** Major version number for Stan package. */
const std::string MAJOR_VERSION = STAN_STRING(STAN_MAJOR);

/** Minor version number for Stan package. */
const std::string MINOR_VERSION = STAN_STRING(STAN_MINOR);

/** Patch version for Stan package. */
const std::string PATCH_VERSION = STAN_STRING(STAN_PATCH);

stan::rng_t rng = util::create_rng(random_seed, chain);

std::vector<double> cont_vector;

Eigen::VectorXd inv_metric;
try {
  cont_vector = util::initialize(model, init, rng, init_radius, true, logger,
                                 init_writer);

  inv_metric = util::read_diag_inv_metric(init_inv_metric,
                                          model.num_params_r(), logger);
  util::validate_diag_inv_metric(inv_metric, logger);
} catch (const std::exception& e) {
  logger.error(e.what());
  return error_codes::CONFIG;
}

stan::mcmc::adapt_diag_e_nuts<Model, stan::rng_t> sampler(model, rng);

sampler.set_metric(inv_metric);
sampler.set_nominal_stepsize(stepsize);
sampler.set_stepsize_jitter(stepsize_jitter);
sampler.set_max_depth(max_depth);

sampler.get_stepsize_adaptation().set_mu(log(10 * stepsize));
sampler.get_stepsize_adaptation().set_delta(delta);
sampler.get_stepsize_adaptation().set_gamma(gamma);
sampler.get_stepsize_adaptation().set_kappa(kappa);
sampler.get_stepsize_adaptation().set_t0(t0);

sampler.set_window_params(num_warmup, init_buffer, term_buffer, window,
                          logger);

try {
  util::run_adaptive_sampler(sampler, model, cont_vector, num_warmup,
                             num_samples, num_thin, refresh, save_warmup, rng,
                             interrupt, logger, sample_writer,
                             diagnostic_writer, metric_writer);
} catch (const std::exception& e) {
  logger.error(e.what());
  return error_codes::SOFTWARE;
}
return error_codes::OK;

Eigen::Map<Eigen::VectorXd> cont_params(cont_vector.data(),
                                        cont_vector.size());

sampler.engage_adaptation();
try {
  sampler.z().q = cont_params;
  sampler.init_stepsize(logger);
} catch (const std::exception& e) {
  logger.error("Exception initializing step size.");
  logger.error(e.what());
  return;
}

services::util::mcmc_writer writer(sample_writer, diagnostic_writer, logger);
stan::mcmc::sample s(cont_params, 0, 0);

// Headers
writer.write_sample_names(s, sampler, model);
writer.write_diagnostic_names(s, sampler, model);

auto start_warm = std::chrono::steady_clock::now();
util::generate_transitions(sampler, num_warmup, 0, num_warmup + num_samples,
                           num_thin, refresh, save_warmup, true, writer, s,
                           model, rng, interrupt, logger, chain_id,
                           num_chains);
auto end_warm = std::chrono::steady_clock::now();
double warm_delta_t = std::chrono::duration_cast<std::chrono::milliseconds>(
                          end_warm - start_warm)
                          .count()
                      / 1000.0;
sampler.disengage_adaptation();
writer.write_adapt_finish(sampler);
sampler.write_sampler_state(sample_writer);
sampler.write_sampler_state_struct(metric_writer);

sampler.disengage_adaptation();
writer.write_adapt_finish(sampler);
sampler.write_sampler_state(sample_writer);
sampler.write_sampler_state_struct(metric_writer);

auto start_sample = std::chrono::steady_clock::now();
util::generate_transitions(sampler, num_samples, num_warmup,
                           num_warmup + num_samples, num_thin, refresh, true,
                           false, writer, s, model, rng, interrupt, logger,
                           chain_id, num_chains);
auto end_sample = std::chrono::steady_clock::now();
double sample_delta_t = std::chrono::duration_cast<std::chrono::milliseconds>(
                            end_sample - start_sample)
                            .count()
                        / 1000.0;
writer.write_timing(warm_delta_t, sample_delta_t);

  throw std::runtime_error(
      "Posterior is improper. "
      "Please check your model.");
if (this->nom_epsilon_ == 0)
  throw std::runtime_error(
      "No acceptably small step size could "
      "be found. Perhaps the posterior is "
      "not continuous?");

param_names.push_back("lp__");
param_names.push_back("path__");
model.constrained_param_names(param_names, true, true);
parameter_writer(param_names);
// All work is done in the parallel_for loop
if (!psis_resample || !calculate_lp) {
  try {
    std::atomic<int> num_path_successes{0};
    stan::callbacks::concurrent_writer safe_write{parameter_writer};
    tbb::parallel_for(
        tbb::blocked_range<int>(0, num_paths),
        [&](tbb::blocked_range<int> r) {
          for (int iter = r.begin(); iter < r.end(); ++iter) {
            // For no psis, have single write to both single and multi writers
            using multi_writer_t = stan::callbacks::tee_writer<
                SingleParamWriter,
                stan::callbacks::concurrent_writer<ParamWriter>>;
            multi_writer_t multi_param_writer(
                single_path_parameter_writer[iter], safe_write);
            auto pathfinder_ret
                = stan::services::pathfinder::pathfinder_lbfgs_single<false,
                                                                      true>(
                    model, *(init[iter]), random_seed, stride_id + iter,
                    init_radius, history_size, init_alpha, tol_obj,
                    tol_rel_obj, tol_grad, tol_rel_grad, tol_param,
                    num_iterations, num_elbo_draws, num_draws,
                    save_iterations, refresh, interrupt, logger,
                    init_writers[iter], multi_param_writer,
                    single_path_diagnostic_writer[iter], calculate_lp);
            if (pathfinder_ret != error_codes::OK) {
              logger.error(std::string("Pathfinder iteration: ")
                           + std::to_string(iter) + " failed.");
              return;
            }
            num_path_successes++;
          }
        });
    safe_write.wait();
    if (unlikely(num_path_successes == 0)) {
      logger.error("No pathfinders ran successfully.");
      return error_codes::SOFTWARE;
    } else if (unlikely(num_path_successes < num_paths)) {
      std::string msg = std::string("Only ")
                        + std::to_string(num_path_successes.load())
                        + std::string(" of the ") + std::to_string(num_paths)
                        + std::string(" pathfinders succeeded.");
      logger.warn(msg);
    }
  } catch (const std::exception& e) {
    logger.error(e.what());
    return error_codes::SOFTWARE;
  }
  double pathfinders_delta_time = stan::services::util::duration_diff(
      start_pathfinders_time, std::chrono::steady_clock::now());
  write_times<true, false>(parameter_writer, pathfinders_delta_time, 0);
  // Writes are done in loop, so just return
  return error_codes::OK;

throw_sampler_warnings <- function(object) {
  if (!is(object, "stanfit"))
    stop("'object' must be of class 'stanfit'")

  if (isTRUE(object@stan_args[[1]][["algorithm"]] == "Fixed_param")) {
    return(invisible(NULL))
  }

  sp <- get_sampler_params(object, inc_warmup = FALSE)
  n_d <- sum(sapply(sp, FUN = function(x) {
    if ("divergent__" %in% colnames(x)) return(sum(x[,"divergent__"]))
    else return(0)
  }))
  if (n_d > 0) {
    ad <- object@stan_args[[1]]$control
    if (is.null(ad)) ad <- 0.8
    else {
      ad <- ad$adapt_delta
      if (is.null(ad)) ad <- 0.8
    }
    warning("There were ", n_d, " divergent transitions after warmup. See\n",
            "https://mc-stan.org/misc/warnings.html#divergent-transitions-after-warmup\n",
            "to find out why this is a problem and how to eliminate them.", call. = FALSE)
  }
  max_td <- object@stan_args[[1]]$control
  if (is.null(max_td)) max_td <- 10
  else {
    max_td <- max_td$max_treedepth
    if (is.null(max_td)) max_td <- 10
  }
  n_m <- sum(sapply(sp, FUN = function(x) {
    if ("treedepth__" %in% colnames(x)) return(sum(x[,"treedepth__"] >= max_td))
    else return(0)
  }))
  if (n_m > 0)
    warning("There were ", n_m,
            " transitions after warmup that exceeded the maximum treedepth.",
            " Increase max_treedepth above ", max_td, ". See\n",
            "https://mc-stan.org/misc/warnings.html#maximum-treedepth-exceeded", call. = FALSE)

## if node is the root of a posterior predictive (entirely non-data) network of nodes, assign 'posterior_predictive' sampler
if(node %in% nodesForPosteriorPredictiveSampler) { addSampler(target = node, type = 'posterior_predictive', control = controlDefaultsArg);     next }

## for multivariate nodes, either add a conjugate sampler, RW_multinomial, or RW_block sampler
if(nodeLength > 1) {
    if(model$isMixedData(node)) {
        if(nodeDist == 'dmnorm') {
            thisControlList <- c(controlDefaultsArg, multivariateNodesAsScalars = multivariateNodesAsScalars)
            addSampler(target = node, type = 'partial_mvn', control = thisControlList, allowData = TRUE) ; next
        }
        stop(paste0('The node ', node, ' is partially observed. NIMBLE only handles this case for multivariate normal distibutions.'))
    } 
    if(useConjugacy) {
        conjugacyResult <- conjugacyResultsAll[[node]]
        if(!is.null(conjugacyResult)) {
            addConjugateSampler(conjugacyResult = conjugacyResult,
                                dynamicallyIndexed = model$modelDef$varInfo[[model$getVarNames(nodes=node)]]$anyDynamicallyIndexed);     next }

sampler_posterior_predictive <- nimbleFunction(
    name = 'sampler_posterior_predictive',
    contains = sampler_BASE,
    setup = function(model, mvSaved, target, control) {
        ## node list generation
        simNodes  <- model$getDependencies(target, downstream = TRUE, includePredictive = TRUE)
        calcNodes <- model$getDependencies(target, downstream = TRUE, includePredictive = TRUE, stochOnly = TRUE)
        ## checks
        if(!all(model$expandNodeNames(target) %in% model$getNodeNames(predictiveOnly = TRUE)))
            stop('posterior_predictive sampler should not be assigned to non-posterior-predictive nodes')
    },
    run = function() {
        model$simulate(simNodes)     ## simulate values of all downstream dependent nodes (stoch and determ both)
        model$calculate(calcNodes)   ## update logProbs of dependent stochastic nodes
        nimCopy(from = model, to = mvSaved, row = 1, nodes = simNodes, logProb = TRUE)
    },
    methods = list(
        reset = function() { }
    )

for(chain in 1:nchains) {
    messageIfVerbose('running chain ', chain, '...')
    if(is.numeric(setSeed)) {
        if(length(setSeed) != nchains) stop('setSeed argument has different length from nchains.')
        set.seed(setSeed[chain])
    } else if(setSeed) set.seed(chain)
    if(!missing(inits)) {
        if(is.function(inits)) {
            theseInits <- inits()
        } else if(is.list(inits) && (length(inits) > 0) && is.list(inits[[1]])) {
            theseInits <- inits[[chain]]
        } else theseInits <- inits
        model$setInits(theseInits)
    }
    ##model$calculate()   # shouldn't be necessary, since mcmc$run() includes call to my_initializeModel$run()
    mcmc$run(niter,
             nburnin = nburnin,
             thin = thinToUseVec[1],
             thin2 = thinToUseVec[2],
             progressBar = progressBar,
             resetWAIC = ifelse(chain == 1, TRUE, FALSE),
             chain = chain
             ## samplerExecutionOrder = samplerExecutionOrderToUse
             )

if(nburnin > niter) stop('cannot specify nburnin > niter')
if(firstRun)   reset <- TRUE       ## compulsory reset on first run of MCMC
firstRun <<- FALSE
mvSamples_copyRow  <- 0
mvSamples2_copyRow <- 0
if(reset) {
    if(initializeModel)   my_initializeModel$run()
    thinToUseVec <<- thinFromConfVec
    if(thin  != -1)   thinToUseVec[1] <<- thin
    if(thin2 != -1)   thinToUseVec[2] <<- thin2
    for(i in seq_along(derivedFunctions)) {
        if(derivedIntervals[i] == 0) {
            derivedIntervals[i] <<- thinToUseVec[1]
            derivedFunctions[[i]]$set_interval(thinToUseVec[1])
        }
    }
    for(i in seq_along(samplerFunctions))   samplerFunctions[[i]]$reset()
    for(i in seq_along(derivedFunctions))   derivedFunctions[[i]]$reset()
    for(i in seq_along(samplerFunctions))   samplerFunctions[[i]]$before_chain(niter,         nburnin,               chain)
    for(i in seq_along(derivedFunctions))   derivedFunctions[[i]]$before_chain(niter-nburnin, nburnin, thinToUseVec, chain)
    samplerTimes <<- numeric(length(samplerFunctions) + 1)       ## default inititialization to zero
    iterationTotal <<- 0
    iterUntilSaveVec <<- thinToUseVec
} else {
    if(nburnin != 0)   stop('cannot specify nburnin when using reset = FALSE.')
    ## now allowing changing of thin and thin2, when reset = FALSE; Jan 2026.
    ## when reset = FALSE and a new value of thin (or thin2) is provided,
    ## issue a warning if the previous MCMC run didn't exactly finish a thinning/save cycle.
    ## this is checked using iterUntilSaveVec[1] == thinToUseVec[1] or iterUntilSaveVec[2] == thinToUseVec[2],
    ## which means saving on the previous thinning interval just took place.
    if((thin  != -1) & (thin  != thinToUseVec[1])) {
        if((iterUntilSaveVec[1] != thinToUseVec[1]) & warnUnfinishedThinningInterval)
            cat('Warning: value of thin is being changed, in the midst of a thinning interval.\n')
        thinToUseVec[1]     <<- thin
        iterUntilSaveVec[1] <<- thin
    }
    if((thin2 != -1) & (thin2 != thinToUseVec[2])) {
        if((iterUntilSaveVec[2] != thinToUseVec[2]) & warnUnfinishedThinningInterval)
            cat('Warning: value of thin2 is being changed, in the midst of a thinning interval.\n')
        thinToUseVec[2]     <<- thin2
        iterUntilSaveVec[2] <<- thin2
    }
    if(dim(samplerTimes)[1] != length(samplerFunctions) + 1)   samplerTimes <<- numeric(length(samplerFunctions) + 1)   ## first run: default inititialization to zero
    if(!resetMV) {
        mvSamples_copyRow  <- getsize(mvSamples)
        mvSamples2_copyRow <- getsize(mvSamples2)
    }
}
for(iThin in 1:2) {
    if(thinToUseVec[iThin] < 1)   stop('cannot use thin < 1')
    if(thinToUseVec[iThin] != floor(thinToUseVec[iThin]))   stop('cannot use non-integer thin')
}
nimCopy(from = model, to = mvSaved, row = 1, logProb = TRUE)
if(onlineWAIC & resetWAIC)   waicFun[[1]]$reset()
resize(mvSamples,  mvSamples_copyRow  + 1 + floor((niter-nburnin-iterUntilSaveVec[1]) / thinToUseVec[1]))
resize(mvSamples2, mvSamples2_copyRow + 1 + floor((niter-nburnin-iterUntilSaveVec[2]) / thinToUseVec[2]))

