public static class MetropolisHastingsBuilder {
    private KeanuRandom random = KeanuRandom.getDefaultRandom();
    private ProposalDistribution proposalDistribution = new PriorProposalDistribution();
    private MHStepVariableSelector variableSelector = DEFAULT_VARIABLE_SELECTOR;
    private ProposalRejectionStrategy rejectionStrategy = new RollBackToCachedValuesOnRejection();

private NUTSSampler setupSampler(final ProbabilisticModelWithGradient model,
                                 final List<? extends Variable> sampleFromVariables) {

    Preconditions.checkArgument(!sampleFromVariables.isEmpty(), "List of variables to sample from is empty");

    final List<? extends Variable<DoubleTensor, ?>> latentVariables = model.getContinuousLatentVariables();

    Map<VariableReference, DoubleTensor> position = latentVariables.stream()
        .collect(toMap(Variable::getReference, Variable::getValue));

    double initialLogOfMasterP = model.logProb(position);

    Preconditions.checkArgument(
        !ProbabilityCalculator.isImpossibleLogProb(initialLogOfMasterP),
        "Sampler starting position is invalid. Please start from a non-zero probability position."
    );

    Map<? extends VariableReference, DoubleTensor> gradient = model.logProbGradients();

    Map<VariableReference, ?> startingSample = SamplingAlgorithm.takeSample(sampleFromVariables);

    double startingStepSize = (initialStepSize == null) ?
        findStartingStepSize(0.25, latentVariables) :
        initialStepSize;

    AdaptiveStepSize stepSize = new AdaptiveStepSize(
        startingStepSize,
        targetAcceptanceProb,
        adaptCount
    );

    potential.initialize(position);
    Proposal initialProposal = new Proposal(position, gradient, startingSample, initialLogOfMasterP);

    return new NUTSSampler(
        sampleFromVariables,
        model,
        adaptPotentialEnabled,
        potential,
        adaptStepSizeEnabled,
        stepSize,
        adaptCount,
        maxEnergyChange,
        maxTreeHeight,
        initialProposal,
        random,
        statistics,
        saveStatistics

public static class NUTSBuilder {

    //NUTS defaults
    private KeanuRandom random = KeanuRandom.getDefaultRandom();
    private long adaptCount = 1000;
    private boolean adaptStepSizeEnabled = true;
    private Double initialStepSize = null;
    private Potential potential = new AdaptiveQuadraticPotential(0, 1, 10.0, 100);
    private boolean adaptPotentialEnabled = true;
    private double targetAcceptanceProb = 0.8;
    private double maxEnergyChange = 1000.0;
    private int maxTreeHeight = 10;
    private boolean saveStatistics = false;

public NetworkSamples generate(final int totalSampleCount) {
    Preconditions.checkArgument(dropCount < totalSampleCount,
        "Cannot drop more samples than requested or all of the samples. Samples requested %s and dropping %s",
        totalSampleCount, dropCount
    );

    StatusBar statusBar = statusBarSupplier.get();

    Map<VariableReference, List<?>> samplesByVariable = new HashMap<>();
    List<Double> logOfMasterPForEachSample = new ArrayList<>();

    dropSamples(dropCount, statusBar);

    PercentageComponent statusPercentage = newPercentageComponentAndAddToStatusBar(statusBar);
    RemainingTimeComponent remainingTimeComponent = new RemainingTimeComponent(totalSampleCount);
    statusBar.addComponent(remainingTimeComponent);
    statusBar.setMessage("Sampling...");
    int sampleCount = 0;
    int samplesLeft = totalSampleCount - dropCount;
    for (int i = 0; i < samplesLeft; i++) {
        if (i % downSampleInterval == 0) {
            algorithm.sample(samplesByVariable, logOfMasterPForEachSample);
            sampleCount++;
        } else {
            algorithm.step();
        }
        remainingTimeComponent.step();
        statusPercentage.progress((double) (i + 1) / samplesLeft);
    }

    statusBar.finish();
    return new NetworkSamples(samplesByVariable, logOfMasterPForEachSample, sampleCount);

if (saveStatistics) {
    stepSize.save(statistics);
    tree.save(statistics);
}

if (this.adaptStepSizeEnabled) {
    stepSize.adaptStepSize(tree);
}

if (stepCount < adaptCount && this.adaptPotentialEnabled) {
    potential.update(proposal.getPosition());
}

if (stepCount > adaptCount) {
    if (tree.isDiverged()) {
        statistics.store(NUTS.Metrics.DIVERGENT_SAMPLE, (double) stepCount);
        log.warn("Divergent NUTS sample after adaption ended. Increase the number or samples to adapt for or the max energy change.");
    }
}

stepCount++;

function DynamicPPL.init(
    rng::Random.AbstractRNG, vn::VarName, ::Distribution, init_strat::InitFromCondDists
)
    return DynamicPPL.TransformedValue(
        rand(rng, _cond_dist_for(init_strat.cond_dists, vn)), DynamicPPL.NoTransform()
    )
end

# `GibbsConditional` needs the conditioning Gibbs supplies, and returns no transition, so on
# its own it yields neither the right target nor a usable chain. Gibbs is the only caller that
# discards the sample, which is how we tell the two apart.
function error_if_outside_gibbs(discard_sample::Bool)
    discard_sample && return nothing
    return throw(
        ArgumentError(
            "GibbsConditional can only be used as a component of Gibbs. " *
            "Are you trying to use GibbsConditional outside of Gibbs?",
        ),
    )
end

function AbstractMCMC.step(
    rng::Random.AbstractRNG,
    model::DynamicPPL.Model,
    ::GibbsConditional;
    initial_params,
    discard_sample::Bool=false,
    kwargs...,
)
    error_if_outside_gibbs(discard_sample)
    accs = DynamicPPL.OnlyAccsVarInfo(DynamicPPL.RawValueAccumulator(false))
    _, accs = DynamicPPL.init!!(rng, model, accs, initial_params, DynamicPPL.UnlinkAll())
    # Since GibbsConditional is only used within Gibbs, it does not need to return a
    # transition.
    return nothing, accs
